-- ----------------------------
-- Records of client_news
-- ----------------------------
BEGIN;
INSERT INTO `client_news` VALUES (3, '物业管理通知1', '<p>尊敬的车主：</p><p>您好！为了能对小区内的机动车实行规范化的管理，我管理处提醒各位车主：如果您办了月租，那您手中的月卡就是凭证，请在进出大门时候一定要交给护卫查验。如不能出示月卡，那只能视为临停收费。同时，如果您的月租到期了，请及时到管理处办理手续，逾期未办理手续的车辆，当您进出小区时我们将按临停收费。</p><p>护卫在您进小区时将给您开具“进出凭条”，此条是您车辆进出小区的重要凭证，因此请车主保管好该凭条。如果您不小心遗失了，为了您的车辆安全，请及时通知管理处，并到管理处办理遗失手续。我管理处将严格按照此规定检查月卡和凭条，由此给您带来的不便，深表歉意，谢谢您的合作！</p><p>特此通知</p><p><br></p>', 1647668185129);
INSERT INTO `client_news` VALUES (4, '物业管理通知2', '<p>尊敬的各位业主及各装修单位：</p><p>为了确保电梯的合理使用、正常运行和大厦物业的有序管理。请遵守大厦电梯管理规定：</p><p>1、一号和二号为客用电梯，行人请使用此电梯；</p><p>2、三号电梯为货运电梯，货物运输请使用此电梯；</p><p>3、请遵守规定的乘坐人数和承载重量，超载时警报鸣响，轿门不会关闭，因此，请最后搭乘的客人退出或卸载超重货物；</p><p>4、在轿厢内蹦跳时有可能使安全装置动作，电梯在途中停止运行，造成故障的原因，因此请静静乘用；</p><p>5、请勿随意或乱按候梯厅或轿厢内的按钮；</p><p>6、电梯内禁止吸烟，为了乘用电梯时，心情愉快，请遵守规定；</p><p>7、开闭电梯时，有危险，请注意勿碰到门或依靠门边站立；</p><p>9、火灾、地震时的避难，请勿使用电梯。</p><p>爱护公物人人有责，请各位业主及装修单位遵守大厦电梯管理规定，配合我们的管理工作！</p>', 1647668217174);
INSERT INTO `client_news` VALUES (5, '物业管理通知3', '<p>各位业主朋友们：</p><p>大家好！</p><p>如果您的物业费尚未交齐或即将到期，请您见到通知单后，到阳光100客户中心（东园6号楼）缴纳物业管理费。如有不便请与管家联系，您的管家将会上门收取。</p><p>感谢您对我公司工作的支持和配合，及时缴纳相关费用才能使物业公司更好地为您服务，祝您天天开心！</p><p>客户中心财务电话xx如果您对我们的服务有不满意的地方，欢迎及时反映！</p>', 1647668240800);
INSERT INTO `client_news` VALUES (6, '物业管理通知4', '<p>尊敬的业主：</p><p>大家好！</p><p>感谢广大业主一直以来对盛世华庭的关注与支持！正是有了大家的支持，才使我们的物业服务品质不断地提升。物业管理费收入是物业公司提高服务的基础和各项开支的来源，是小区治安秩序、环境绿化及卫生、房屋公共设施配套管理的根本保证。</p><p>（催费年限）年工作已接近尾声，至今仍有部分业主未能按时缴纳物业管理费。如果物业管理费不能按时缴纳，将会对物业管理服务工作造成严重的影响。同时，严重侵犯了已交费业主的切身利益，为此我们再次郑重提示，根据《（物业管理项目名称）物业服务协会或（前期物业服务协议）》，业主或物业使用人有义务向物业管理公司按（交费周期）在首季（交费日期）交纳物业管理费，逾期未缴纳，从逾期之日起将产生违约金。</p><p>请拖欠多年物业管理费的业主在（规定的日期）前，将拖欠多年的物业费一并交齐。对逾期不交物业管理费的业主，物业公司将秉公办事，按照《物权法》及《物业管理条例》的相关规定依法进行追缴拖欠的全额物业费，并从逾期之日起收取违约金。</p><p>物业管理费应缴金额您可前往物业管理处或致电（服务电话）查询，如您平时工作繁忙，也可通过汇款的方式缴纳。</p>', 1647668265116);
INSERT INTO `client_news` VALUES (7, '物业管理通知5', '<p>尊敬的业主/住户：</p><p>您好，春节将至，为了让大家能过一个安全、温馨和舒适的节日。我管理处在加强出入口控制和日常巡逻的同时提醒各位业主和住户：</p><p>1、外出时，注意关好门窗以及水、电、气的开关，同时请保管好自己的贵重物品，以免发生火灾和失窃。</p><p>2、请您将车辆停放在指定位置，以免丢失；如您长时间外出，而车辆停放在小区内，请通知管理处。</p><p>3、请不要随意给陌生人开门，以防不测。</p><p>4、在使用电器及天然气时，请注意用电用火安全。</p><p>5、春节期间，小区内禁止燃放烟花爆竹。</p><p>6、请不要让您的小孩到水池边玩耍，以免出现安全事故。</p><p>7、商铺的商家在节日期间如要歇业，店内请留人值守（特别在夜间），以防意外发生。</p>', 1647668287226);
INSERT INTO `client_news` VALUES (8, '物业管理通知7', '<p>日前，中站区新生小学、府城中心学校先后组织人员对学校靠近路边高压、低压线路的树木进行了去枝修理，及时消除了可能触电的安全隐患。进入冬季以来，中站区教育局非常重视中小学和幼儿园冬季安全教育，积极采取多种形式狠抓校园安全工作，努力确保校园“零事故”。</p><p>防患于未然，扎实开展“冬季四防”教育活动。认真开展“冬季四防”安全知识进校园活动，努力普及安全常识，提高广大师生自我防护能力。中站区教育局以“加强防范，强化教育，普及常识，提高能力”为目标，不断加大冬季安全知识教育普及力度，扎实开展了以预防火灾、预防盗窃、预防煤气中毒、预防交通事故为内容的“冬季四防”安全知识进校园活动。中站区教育局要求全区中小学克服侥幸麻痹思想，以高度负责的精神抓好冬季校园安全工作，扎实开展“冬季四防”安全知识进校园活动，切实抓出成效，努力保持“校园零事故”。辖区中小学开展了多种形式的“冬季四防”安全知识宣传教育活动，在校园显著位置设立了宣传教育专栏，每个班至少办一期“冬季四防”安全知识板报，至少召开一次宣传冬季安全知识班会。同时，积极将冬季安全教育渗透到各学科教学和各项活动当中，努力让安全知识进师生头脑，全力提高师生去年全年防范意识。</p><p>扎实开展“冬季安全隐患大排查”活动，及时消灭隐患。深入细致开展“冬季校园安全隐患大排查”活动，辖区中小学对照安全工作相关标准，进行全面、细致、认真的安全隐患大排查，对于发现的问题逐项登记，明确责任人和整改期限，做到安全细节“不漏查”，安全隐患“不漏登”，安全整改“无死角”。</p><p>一是排查灭火器材配备情况，相关处室、楼层、关键部位灭火器数量是否达标，是否超期使用，楼层灭火水源是否畅通。二是排查重点部位监控设备工作情况。监控设施设备数量是充足，是否有有损坏，摄像头是否清晰，是否能够一天24小时正常工作。三是排查线路隐患，线路是否老化，走线是否规整，线头是否裸露松动，是否有私搭电线乱用电情况，排查宿舍、办公室是否有使用大功率取暖电器现象；四是排查食堂煤气灶是否紧挨煤气罐，油烟管道是否定期清洗，实验室易燃、易爆等危险品是否规范存放；五是排查疏散通道和安全出口有无被占用、堵塞、封闭等；六是排查门岗管理是否严格规范，对外来人员是否严格实行登记出入制度；七是排查放学路队是否按照要求有专人值守，放学秩序是否良好；八是排查火炉取暖隐患，火炉排气管道是否畅通漏气，管理环节是否规范。九是排查体育等设施是否有松动脱落现象，焊接部位是否有脱落现象。通过对冬季易发隐患排查，及时消除隐患100多起，保障了师生的`生命和财产安全。</p><p>多部门联动治理综合治理，优化校园周边环境。区教育局联合办事处、工商、公安等部门，不断优化辖区内学校周边环境，保证了无校外人员扰乱学校秩序事件发生；切实抓好学校周边环境治理和法制宣传教育工作，严厉打击危害校园安全和师生合法权益等行为，坚决严厉打击侵犯师生权益的违法违纪事件，创造安全稳定的教育环境，依法保障学校及教师、学生的合法权益，对侵犯师生权益的违法违纪事件处理及时、坚决。加强学校周边环境治理和文化市场的管理，取缔接纳未成年人的网吧和电子游戏室等营业场所；加强交通秩序整治，整治学生骑自行车、电动车上快车道现象；安排警力在学校上下学时间段巡逻，确保学生人身安全。加强学校周边文化市场的管理，取缔接纳未成年人的网吧和电子游戏室等营业场所；依法治理文化市场，净化文化环境，查禁有害于青少年身心健康的文化娱乐项目和非法出版物。优化学校周边环境，加强对游商浮贩的管理，严禁在学校门口两侧50米以内设摊贩卖各种物品、食品等。</p><p>细化规范校园安全管理，加强各项制度落实力度。一是严格落实校园安全值班制度，严格领导带班纪律，学校值班电话和负责人电话每天24小时保持畅通。二是加强学校门岗管理，外来任何人员进入学校前先要核实身份，联系人，与联系人接通电话核实后，然后登记才能进入学校。三是加强校园安全设施配备更新，对学校数量不足的灭火器进行购买补充，对过期的灭火器进行充粉。对监控设施数量不足的学校安装监控摄像头，并且保证全部摄像设施能够正常运转使用。四是严格落实好“放学最后一节课一分钟安全教育”，坚持安全常提醒，让安全常挂嘴边。五是开展校园安全督导检查活动。中站区教育局组成三个校园安全督导检查组，分别深入到全区中小学、幼儿园全面检查校园安全，现场发放了《安全隐患反馈单》。同时，对全区中小学、幼儿园检查出来的隐患统一建立了《校园安全隐患整改台账》，明确了整改期限和责任人。之后，又组织3个检查组先后两次深入到分包幼儿园和学校督导安全隐患整改情况，督促、盯紧辖区中小学和幼儿园进行安全隐患整改。六是严格落实“校园安全日报告制度”，每天下午下班前中小学将校园安全情况向区教育局报告。</p><p>进入冬季里来，中站区教育局积极采取多种形式狠抓校园安全工作，全力抓细夯实校园安全工作，努力创建“零事故”校园，全力为师生生命和财产安全筑起一道坚固的防线。</p>', 1647668315761);
COMMIT;

